def count_subarrays_with_gcd(nums,k):
    from math import gcd
    previous={};answer=0
    for value in nums:
        current={value:1}
        for common,count in previous.items():
            reduced=gcd(common,value);current[reduced]=current.get(reduced,0)+count
        answer+=current.get(k,0);previous=current
    return answer

